import 'package:cloud_firestore/cloud_firestore.dart'; import 'package:flutter/material.dart'; class UsersAdminPage extends StatelessWidget{const UsersAdminPage({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Kelola Pengguna')),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('users').snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.docs.map((d){final x=d.data();return ListTile(title:Text(x['name']??x['email']??'Pengguna'),subtitle:Text('Role: '+(x['role']??'user').toString()),trailing:Switch(value:x['active']??true,onChanged:(v)=>d.reference.update({'active':v})));}).toList());}));}